config.content:
#include "bsp_mcu_device_pn_cfg.h" #include "bsp_mcu_device_cfg.h" #include "../../../ra/fsp/src/bsp/mcu/ra8d1/bsp_override.h" #include "../../../ra/fsp/src/bsp/mcu/ra8d1/bsp_mcu_info.h" #include "bsp_clock_cfg.h" #define BSP_MCU_GROUP_RA8D1 (1) #define BSP_LOCO_HZ (32768) #define BSP_MOCO_HZ (8000000) #define BSP_SUB_CLOCK_HZ (0) #if BSP_CFG_HOCO_FREQUENCY == 0 #define BSP_HOCO_HZ (16000000) #elif BSP_CFG_HOCO_FREQUENCY == 1 #define BSP_HOCO_HZ (18000000) #elif BSP_CFG_HOCO_FREQUENCY == 2 #define BSP_HOCO_HZ (20000000) #elif BSP_CFG_HOCO_FREQUENCY == 4 #define BSP_HOCO_HZ (32000000) #elif BSP_CFG_HOCO_FREQUENCY == 7 #define BSP_HOCO_HZ (48000000) #else #error "Invalid HOCO frequency chosen (BSP_CFG_HOCO_FREQUENCY) in bsp_clock_cfg.h" #endif
#define BSP_CFG_FLL_ENABLE (${config.bsp.fsp.hoco_fll})
#define BSP_CFG_CLOCK_SETTLING_DELAY_ENABLE (${config.bsp.fsp.clock_settling_delay}) #define BSP_CFG_SLEEP_MODE_DELAY_ENABLE (${config.bsp.fsp.sleep_mode_delays}) #define BSP_CFG_MSTP_CHANGE_DELAY_ENABLE (${config.bsp.fsp.mstp_change_delays}) #define BSP_CFG_RTOS_IDLE_SLEEP (${config.bsp.fsp.rtos_idle_sleep}) #define BSP_CFG_CLOCK_SETTLING_DELAY_US (${config.bsp.fsp.settling_delay_us})
#if defined(BSP_PACKAGE_LQFP) && (BSP_PACKAGE_PINS == 100) #define BSP_MAX_CLOCK_CHANGE_THRESHOLD (180000000U) #elif defined(BSP_PACKAGE_LQFP) #define BSP_MAX_CLOCK_CHANGE_THRESHOLD (200000000U) #else #define BSP_MAX_CLOCK_CHANGE_THRESHOLD (240000000U) #endif
#define BSP_CORTEX_VECTOR_TABLE_ENTRIES (16U) #define BSP_VECTOR_TABLE_MAX_ENTRIES (112U) #define BSP_CFG_INLINE_IRQ_FUNCTIONS (${config.bsp.fsp.inline_irq_functions})
#if defined(_RA_TZ_SECURE) #define BSP_TZ_SECURE_BUILD (1) #define BSP_TZ_NONSECURE_BUILD (0) #elif defined(_RA_TZ_NONSECURE) #define BSP_TZ_SECURE_BUILD (0) #define BSP_TZ_NONSECURE_BUILD (1) #else #define BSP_TZ_SECURE_BUILD (0) #define BSP_TZ_NONSECURE_BUILD (0) #endif
/* TrustZone Settings */ #define BSP_TZ_CFG_INIT_SECURE_ONLY (BSP_CFG_CLOCKS_SECURE || (!BSP_CFG_CLOCKS_OVERRIDE)) #define BSP_TZ_CFG_SKIP_INIT (BSP_TZ_NONSECURE_BUILD && BSP_TZ_CFG_INIT_SECURE_ONLY) #define BSP_TZ_CFG_EXCEPTION_RESPONSE (${config.bsp.fsp.tz.exception_response})
/* CMSIS TrustZone Settings */ #define SCB_CSR_AIRCR_INIT (1) #define SCB_AIRCR_BFHFNMINS_VAL (${config.bsp.fsp.tz.cmsis.bfhfnmins}) #define SCB_AIRCR_SYSRESETREQS_VAL (${config.bsp.fsp.tz.cmsis.sysresetreqs}) #define SCB_AIRCR_PRIS_VAL (${config.bsp.fsp.tz.cmsis.s_priority_boost}) #define TZ_FPU_NS_USAGE (1) #ifndef SCB_NSACR_CP10_11_VAL #define SCB_NSACR_CP10_11_VAL (3U) #endif
#ifndef FPU_FPCCR_TS_VAL #define FPU_FPCCR_TS_VAL (1U) #endif #define FPU_FPCCR_CLRONRETS_VAL (1)
#ifndef FPU_FPCCR_CLRONRET_VAL #define FPU_FPCCR_CLRONRET_VAL (1) #endif
/* Type 1 Peripheral Security Attribution */
/* Peripheral Security Attribution Register (PSAR) Settings */ #ifndef BSP_TZ_CFG_PSARB #define BSP_TZ_CFG_PSARB (\ (((${interface.peripheral.i3c} > 0) ? 0U : 1U) << 4) /* I3C */ | \ (((${interface.peripheral.iic1} > 0) ? 0U : 1U) << 8) /* IIC1 */ | \ (((${interface.peripheral.iic0} > 0) ? 0U : 1U) << 9) /* IIC0 */ | \ (((${interface.peripheral.usbfs} > 0) ? 0U : 1U) << 11) /* USBFS */ | \ (((${interface.peripheral.usbhs} > 0) ? 0U : 1U) << 12) /* USBHS */ | \ (1 << 15) /* ETHERC/EDMAC */ | \ (1 << 16) /* OSPI */ | \ (((${interface.peripheral.spi1} > 0) ? 0U : 1U) << 18) /* SPI1 */ | \ (((${interface.peripheral.spi0} > 0) ? 0U : 1U) << 19) /* SPI0 */ | \ (((${interface.peripheral.sci9} > 0) ? 0U : 1U) << 22) /* SCI9 */ | \ (((${interface.peripheral.sci4} > 0) ? 0U : 1U) << 27) /* SCI4 */ | \ (((${interface.peripheral.sci3} > 0) ? 0U : 1U) << 28) /* SCI3 */ | \ (((${interface.peripheral.sci2} > 0) ? 0U : 1U) << 29) /* SCI2 */ | \ (((${interface.peripheral.sci1} > 0) ? 0U : 1U) << 30) /* SCI1 */ | \ (((${interface.peripheral.sci0} > 0) ? 0U : 1U) << 31) /* SCI0 */) #endif #ifndef BSP_TZ_CFG_PSARC #define BSP_TZ_CFG_PSARC (\ (((${interface.peripheral.cac} > 0) ? 0U : 1U) << 0) /* CAC */ | \ (((${interface.peripheral.crc} > 0) ? 0U : 1U) << 1) /* CRC */ | \ (((${interface.peripheral.ssie1} > 0) ? 0U : 1U) << 7) /* SSIE1 */ | \ (((${interface.peripheral.ssie0} > 0) ? 0U : 1U) << 8) /* SSIE0 */ | \ (((${interface.peripheral.sdhi1} > 0) ? 0U : 1U) << 11) /* SDHI1 */ | \ (((${interface.peripheral.sdhi0} > 0) ? 0U : 1U) << 12) /* SDHI0 */ | \ (((${interface.peripheral.doc} > 0) ? 0U : 1U) << 13) /* DOC */ | \ (((${interface.peripheral.glcdc} > 0) ? 0U : 1U) << 15) /* GLCDC/MIPI-DSI/DRW */ | \ (((${interface.peripheral.ceu} > 0) ? 0U : 1U) << 16) /* CEU */ | \ (((${interface.peripheral.canfd1} > 0) ? 0U : 1U) << 26) /* CANFD1 */ | \ (((${interface.peripheral.canfd0} > 0) ? 0U : 1U) << 27) /* CANFD0 */ | \ (((${interface.peripheral.rsip} > 0) ? 0U : 1U) << 31) /* RSIP-E51A */) #endif #ifndef BSP_TZ_CFG_PSARD #define BSP_TZ_CFG_PSARD (\ (((${interface.peripheral.agt1} > 0) ? 0U : 1U) << 4) /* AGT1 */ | \ (((${interface.peripheral.agt0} > 0) ? 0U : 1U) << 5) /* AGT0 */ | \ (((${interface.peripheral.poeg3} > 0) ? 0U : 1U) << 11) /* POEG3 */ | \ (((${interface.peripheral.poeg2} > 0) ? 0U : 1U) << 12) /* POEG2 */ | \ (((${interface.peripheral.poeg1} > 0) ? 0U : 1U) << 13) /* POEG1 */ | \ (((${interface.peripheral.poeg0} > 0) ? 0U : 1U) << 14) /* POEG0 */ | \ (((${interface.peripheral.adc1} > 0) ? 0U : 1U) << 15) /* ADC121 */ | \ (((${interface.peripheral.adc0} > 0) ? 0U : 1U) << 16) /* ADC120 */ | \ (((${interface.peripheral.dac0} > 0) ? 0U : 1U) << 20) /* DAC120 */ | \ (((${interface.peripheral.tsn} > 0) ? 0U : 1U) << 22) /* TSN */ | \ (((${interface.peripheral.acmphs1} > 0) ? 0U : 1U) << 27) /* ACMPHS1 */ | \ (((${interface.peripheral.acmphs0} > 0) ? 0U : 1U) << 28) /* ACMPHS0 */) #endif #ifndef BSP_TZ_CFG_PSARE #define BSP_TZ_CFG_PSARE (\ (((${interface.peripheral.wdt} > 0) ? 0U : 1U) << 1) /* WDT */ | \ (((${interface.peripheral.iwdt} > 0) ? 0U : 1U) << 2) /* IWDT */ | \ (((${interface.peripheral.rtc} > 0) ? 0U : 1U) << 3) /* RTC */ | \ (((${interface.peripheral.ulpt1} > 0) ? 0U : 1U) << 8) /* ULPT1 */ | \ (((${interface.peripheral.ulpt0} > 0) ? 0U : 1U) << 9) /* ULPT0 */ | \ (((${interface.peripheral.gpt13} > 0) ? 0U : 1U) << 18) /* GPT13 */ | \ (((${interface.peripheral.gpt12} > 0) ? 0U : 1U) << 19) /* GPT12 */ | \ (((${interface.peripheral.gpt11} > 0) ? 0U : 1U) << 20) /* GPT11 */ | \ (((${interface.peripheral.gpt10} > 0) ? 0U : 1U) << 21) /* GPT10 */ | \ (((${interface.peripheral.gpt9} > 0) ? 0U : 1U) << 22) /* GPT9 */ | \ (((${interface.peripheral.gpt8} > 0) ? 0U : 1U) << 23) /* GPT8 */ | \ (((${interface.peripheral.gpt7} > 0) ? 0U : 1U) << 24) /* GPT7 */ | \ (((${interface.peripheral.gpt6} > 0) ? 0U : 1U) << 25) /* GPT6 */ | \ (((${interface.peripheral.gpt5} > 0) ? 0U : 1U) << 26) /* GPT5 */ | \ (((${interface.peripheral.gpt4} > 0) ? 0U : 1U) << 27) /* GPT4 */ | \ (((${interface.peripheral.gpt3} > 0) ? 0U : 1U) << 28) /* GPT3 */ | \ (((${interface.peripheral.gpt2} > 0) ? 0U : 1U) << 29) /* GPT2 */ | \ (((${interface.peripheral.gpt1} > 0) ? 0U : 1U) << 30) /* GPT1 */ | \ (((${interface.peripheral.gpt0} > 0) ? 0U : 1U) << 31) /* GPT0 */) #endif #ifndef BSP_TZ_CFG_MSSAR #define BSP_TZ_CFG_MSSAR (\ (((${interface.peripheral.dtc_dmac} > 0) ? 0U : 1U) << 22) /* DTC_DMAC */ | \ (((${interface.peripheral.elc} > 0) ? 0U : 1U) << 31) /* ELC */) #endif
/* Type 2 Peripheral Security Attribution */
/* Security attribution for RSTSRn registers. */ #ifndef BSP_TZ_CFG_RSTSAR #define BSP_TZ_CFG_RSTSAR (${config.bsp.fsp.tz.rstsar}) #endif
/* Security attribution for registers of LVD channels. */ #ifndef BSP_TZ_CFG_LVDSAR /* The LVD driver needs to access both channels. This means that the security attribution for both channels must be the same. */ #if (${interface.peripheral.lvdmodule.driver.lvd.monitor_number.MONITOR_1} > 0) || (${interface.peripheral.lvdmodule.driver.lvd.monitor_number.MONITOR_2} > 0) #define BSP_TZ_CFG_LVDSAR (0U) #else #define BSP_TZ_CFG_LVDSAR (3U) #endif #endif
/* Security attribution for LPM registers. * - OPCCR based on clock security. * - Set remaining registers based on LPM security. */ #ifndef BSP_TZ_CFG_LPMSAR #define BSP_TZ_CFG_LPMSAR ((RA_NOT_DEFINED > 0) ? BSP_CFG_CLOCKS_SECURE == 0 : (\ 0x002E0106U | \ (BSP_CFG_CLOCKS_SECURE == 0))) #endif /* Deep Standby Interrupt Factor Security Attribution Register. */ #ifndef BSP_TZ_CFG_DPFSAR #define BSP_TZ_CFG_DPFSAR ((${interface.peripheral.lpm} > 0) ? 0U : 0xAF1FFFFFU) #endif /* RAM Standby Control Security Attribution Register. */ #ifndef BSP_TZ_CFG_RSCSAR #define BSP_TZ_CFG_RSCSAR ((${interface.peripheral.lpm} > 0) ? 0U : 0x00037FFFU) #endif /* Power Gating Control Security Attribution Register */ #ifndef BSP_TZ_CFG_PGCSAR #define BSP_TZ_CFG_PGCSAR ${config.bsp.fsp.tz.pgcsar} #endif
/* Security attribution for CGC registers. */ #ifndef BSP_TZ_CFG_CGFSAR #if BSP_CFG_CLOCKS_SECURE /* Protect all CGC registers from Non-secure write access. */ #define BSP_TZ_CFG_CGFSAR (0U) #else /* Allow Secure and Non-secure write access. */ #define BSP_TZ_CFG_CGFSAR (0x047F3BFDU) #endif #endif
/* Security attribution for Battery Backup registers. */ #ifndef BSP_TZ_CFG_BBFSAR #if ${config.bsp.fsp.tz.bbfsar} #define BSP_TZ_CFG_BBFSAR (0U) #else #define BSP_TZ_CFG_BBFSAR (0x1FU) #endif #endif
/* Security attribution for Battery Backup registers (VBTBKRn). */ #ifndef BSP_TZ_CFG_VBRSABAR #if ${config.bsp.fsp.tz.bbfsar} #define BSP_TZ_CFG_VBRSABAR (0xFFE0) #else #define BSP_TZ_CFG_VBRSABAR (0xED00) #endif #endif
/* Security attribution for registers for IRQ channels. */ #ifndef BSP_TZ_CFG_ICUSARA #define BSP_TZ_CFG_ICUSARA (\ (((${interface.peripheral.irq0} > 0) ? 0U : 1U) << 0U) /* External IRQ0 */ | \ (((${interface.peripheral.irq1} > 0) ? 0U : 1U) << 1U) /* External IRQ1 */ | \ (((${interface.peripheral.irq2} > 0) ? 0U : 1U) << 2U) /* External IRQ2 */ | \ (((${interface.peripheral.irq3} > 0) ? 0U : 1U) << 3U) /* External IRQ3 */ | \ (((${interface.peripheral.irq4} > 0) ? 0U : 1U) << 4U) /* External IRQ4 */ | \ (((${interface.peripheral.irq5} > 0) ? 0U : 1U) << 5U) /* External IRQ5 */ | \ (((${interface.peripheral.irq6} > 0) ? 0U : 1U) << 6U) /* External IRQ6 */ | \ (((${interface.peripheral.irq7} > 0) ? 0U : 1U) << 7U) /* External IRQ7 */ | \ (((${interface.peripheral.irq8} > 0) ? 0U : 1U) << 8U) /* External IRQ8 */ | \ (((${interface.peripheral.irq9} > 0) ? 0U : 1U) << 9U) /* External IRQ9 */ | \ (((${interface.peripheral.irq10} > 0) ? 0U : 1U) << 10U) /* External IRQ10 */ | \ (((${interface.peripheral.irq11} > 0) ? 0U : 1U) << 11U) /* External IRQ11 */ | \ (((${interface.peripheral.irq12} > 0) ? 0U : 1U) << 12U) /* External IRQ12 */ | \ (((${interface.peripheral.irq13} > 0) ? 0U : 1U) << 13U) /* External IRQ13 */ | \ (((${interface.peripheral.irq14} > 0) ? 0U : 1U) << 14U) /* External IRQ14 */ | \ (((${interface.peripheral.irq15} > 0) ? 0U : 1U) << 15U) /* External IRQ15 */) #endif
/* Security attribution for NMI registers. */ #ifndef BSP_TZ_CFG_ICUSARB #define BSP_TZ_CFG_ICUSARB (${config.bsp.fsp.tz.cmsis.bfhfnmins} | 0U) /* Should match AIRCR.BFHFNMINS. */ #endif
/* Security attribution for registers for DMAC channels */ #ifndef BSP_TZ_CFG_DMACCHSAR #define BSP_TZ_CFG_DMACCHSAR (\ (((${interface.peripheral.dmac0} > 0) ? 0U : 1U) << 0U) /* DMAC Channel 0 */ | \ (((${interface.peripheral.dmac1} > 0) ? 0U : 1U) << 1U) /* DMAC Channel 1 */ | \ (((${interface.peripheral.dmac2} > 0) ? 0U : 1U) << 2U) /* DMAC Channel 2 */ | \ (((${interface.peripheral.dmac3} > 0) ? 0U : 1U) << 3U) /* DMAC Channel 3 */ | \ (((${interface.peripheral.dmac4} > 0) ? 0U : 1U) << 4U) /* DMAC Channel 4 */ | \ (((${interface.peripheral.dmac5} > 0) ? 0U : 1U) << 5U) /* DMAC Channel 5 */ | \ (((${interface.peripheral.dmac6} > 0) ? 0U : 1U) << 6U) /* DMAC Channel 6 */ | \ (((${interface.peripheral.dmac7} > 0) ? 0U : 1U) << 7U) /* DMAC Channel 7 */) #endif
/* Security attribution registers for WUPEN0. */ #ifndef BSP_TZ_CFG_ICUSARE #define BSP_TZ_CFG_ICUSARE ((${interface.peripheral.lpm} > 0) ? 0U : 0xFF1D0000U) #endif
/* Security attribution registers for WUPEN1. */ #ifndef BSP_TZ_CFG_ICUSARF #define BSP_TZ_CFG_ICUSARF ((${interface.peripheral.lpm} > 0) ? 0U : 0x00007F08U) #endif
/* Trusted Event Route Control Register for IELSR, DMAC.DELSR and ELC.ELSR. Note that currently Trusted Event Route Control is not supported. */ #ifndef BSP_TZ_CFG_TEVTRCR #define BSP_TZ_CFG_TEVTRCR (0) #endif
/* Security attribution register for ELCR, ELSEGR0, ELSEGR1 Security Attribution. */ #ifndef BSP_TZ_CFG_ELCSARA #define BSP_TZ_CFG_ELCSARA (0x00000007U) #endif
/* Set DTCSTSAR if the Secure program uses the DTC. */ #if ${interface.peripheral.dtc} == RA_NOT_DEFINED #define BSP_TZ_CFG_DTC_USED (0U) #else #define BSP_TZ_CFG_DTC_USED (1U) #endif
/* Security attribution of FLWT and FCKMHZ registers. */ #ifndef BSP_TZ_CFG_FSAR /* If the CGC registers are only accessible in Secure mode, than there is no * reason for nonsecure applications to access FLWT and FCKMHZ. */ #define BSP_TZ_CFG_FSAR (\ ((BSP_CFG_CLOCKS_SECURE == 0) ? (1U << 0) : 0U) | /* FLWTSA */\ ((${interface.peripheral.flash_hp}) > 0 ? 0U: (1U << 1)) | /* FCACHESA */\ ((BSP_CFG_CLOCKS_SECURE == 0) ? (1U << 8) : 0U) | /* FCKMHZSA */ \ ((${interface.peripheral.flash_hp}) > 0 ? 0U : (1U << 9U)) | /* FACICMISA */\ ((${interface.peripheral.flash_hp}) > 0 ? 0U: (1U << 10U)) /* FACICMRSA */) #endif
/* Security attribution for SRAM registers. */ #ifndef BSP_TZ_CFG_SRAMSAR /* If the CGC registers are only accessible in Secure mode, than there is no reason for Non Secure applications to access * SRAM0WTEN and therefore there is no reason to access PRCR2. */ #define BSP_TZ_CFG_SRAMSAR (\ ((${config.bsp.fsp.tz.sramsar.sramsa0}) << 0U) | /* SRAMSA0 */\ ((${config.bsp.fsp.tz.sramsar.sramsa1}) << 1U) | /* SRAMSA1 */\ ((${config.bsp.fsp.tz.sramsar.stbramsa}) << 7U) | /* STBRAMSA */\ ((BSP_CFG_CLOCKS_SECURE == 0) ? (1U << 8U) : 0U) /* SRAMWTSA */) #endif
/* Security attribution for the DMAC Bus Master MPU settings. */ #ifndef BSP_TZ_CFG_MMPUSARA /* The DMAC Bus Master MPU settings should align with the DMAC channel settings. */ #define BSP_TZ_CFG_MMPUSARA (BSP_TZ_CFG_DMACCHSAR) #endif
/* Security Attribution Register A for BUS Control registers. */ #ifndef BSP_TZ_CFG_BUSSARA #define BSP_TZ_CFG_BUSSARA (${config.bsp.fsp.tz.bussara}) #endif /* Security Attribution Register B for BUS Control registers. */ #ifndef BSP_TZ_CFG_BUSSARB #define BSP_TZ_CFG_BUSSARB (${config.bsp.fsp.tz.bussarb}) #endif /* Security Attribution Register C for BUS Control registers. */ #ifndef BSP_TZ_CFG_BUSSARC #define BSP_TZ_CFG_BUSSARC (${config.bsp.fsp.tz.bussarc}) #endif
/* Enable Uninitialized Non-Secure Application Fallback. */ #ifndef BSP_TZ_CFG_NON_SECURE_APPLICATION_FALLBACK #define BSP_TZ_CFG_NON_SECURE_APPLICATION_FALLBACK (${config.bsp.fsp.tz.uninitialized_ns_application_fallback}) #endif
#define OFS_SEQ1 0xA001A001 | (${config.bsp.fsp.OFS0.iwdt_start_mode}) | (${config.bsp.fsp.OFS0.iwdt_timeout}) #define OFS_SEQ2 (${config.bsp.fsp.OFS0.iwdt_divisor}) | (${config.bsp.fsp.OFS0.iwdt_window_end}) | (${config.bsp.fsp.OFS0.iwdt_window_start}) #define OFS_SEQ3 (${config.bsp.fsp.OFS0.iwdt_reset_interrupt}) | (${config.bsp.fsp.OFS0.iwdt_stop_control}) | (${config.bsp.fsp.OFS0.wdt_start_mode}) #define OFS_SEQ4 (${config.bsp.fsp.OFS0.wdt_timeout}) |(${config.bsp.fsp.OFS0.wdt_divisor}) | (${config.bsp.fsp.OFS0.wdt_window_end}) | (${config.bsp.fsp.OFS0.wdt_window_start}) #define OFS_SEQ5 (${config.bsp.fsp.OFS0.wdt_reset_interrupt}) | (${config.bsp.fsp.OFS0.wdt_stop_control}) #define BSP_CFG_ROM_REG_OFS0 (OFS_SEQ1 | OFS_SEQ2 | OFS_SEQ3 | OFS_SEQ4 | OFS_SEQ5)
#define BSP_CFG_ROM_REG_OFS2 ((${config.bsp.fsp.OFS2.dcdc}) | 0xFFFFFFFEU)
/* Option Function Select Register 1 Security Attribution */ #ifndef BSP_CFG_ROM_REG_OFS1_SEL #if defined(_RA_TZ_SECURE) || defined(_RA_TZ_NONSECURE) #define BSP_CFG_ROM_REG_OFS1_SEL (0x00000000U | (${config.bsp.fsp.OFS1_SEL.voltage_detection0_level}) | (${config.bsp.fsp.OFS1_SEL.voltage_detection0.start}) | (${config.bsp.fsp.OFS1_SEL.voltage_detection0.low_power_consumption}) | ((BSP_CFG_CLOCKS_SECURE == 0) ? 0xF00U : 0U) | (${config.bsp.fsp.OFS1_SEL.swdbg}) | (${config.bsp.fsp.OFS1_SEL.initeccen})) #else #define BSP_CFG_ROM_REG_OFS1_SEL (0x00000000U) #endif #endif #define BSP_CFG_ROM_REG_OFS1_INITECCEN (${config.bsp.fsp.OFS1.initeccen}) #define BSP_CFG_ROM_REG_OFS1 (0xFCFFFED0 | (${config.bsp.fsp.OFS1.voltage_detection0.start}) | (${config.bsp.fsp.OFS1.voltage_detection0_level}) | (${config.bsp.fsp.OFS1.voltage_detection0.low_power_consumption}) | (${config.bsp.fsp.OFS1.hoco_osc}) | (${config.bsp.fsp.OFS1.swdbg}) | (BSP_CFG_ROM_REG_OFS1_INITECCEN))
/* Used to create IELS values for the interrupt initialization table g_interrupt_event_link_select. */ #define BSP_PRV_IELS_ENUM(vector) (ELC_ ## vector)
/* Dual Mode Select Register */ #ifndef BSP_CFG_ROM_REG_DUALSEL #define BSP_CFG_ROM_REG_DUALSEL (0xFFFFFFF8U | (${config.bsp.fsp.dual_bank})) #endif
/* Block Protection Register 0 */ #ifndef BSP_CFG_ROM_REG_BPS0 #define BSP_CFG_ROM_REG_BPS0 (~(${config.bsp.fsp.BPS.BPS0} 0U)) #endif /* Block Protection Register 1 */ #ifndef BSP_CFG_ROM_REG_BPS1 #define BSP_CFG_ROM_REG_BPS1 (~(${config.bsp.fsp.BPS.BPS1} 0U)) #endif /* Block Protection Register 2 */ #ifndef BSP_CFG_ROM_REG_BPS2 #define BSP_CFG_ROM_REG_BPS2 (~(${config.bsp.fsp.BPS.BPS2} 0U)) #endif /* Block Protection Register 3 */ #ifndef BSP_CFG_ROM_REG_BPS3 #define BSP_CFG_ROM_REG_BPS3 (~(${config.bsp.fsp.BPS.BPS3} 0U)) #endif /* Permanent Block Protection Register 0 */ #ifndef BSP_CFG_ROM_REG_PBPS0 #define BSP_CFG_ROM_REG_PBPS0 (~(${config.bsp.fsp.PBPS.PBPS0} 0U)) #endif /* Permanent Block Protection Register 1 */ #ifndef BSP_CFG_ROM_REG_PBPS1 #define BSP_CFG_ROM_REG_PBPS1 (~(${config.bsp.fsp.PBPS.PBPS1} 0U)) #endif /* Permanent Block Protection Register 2 */ #ifndef BSP_CFG_ROM_REG_PBPS2 #define BSP_CFG_ROM_REG_PBPS2 (~(${config.bsp.fsp.PBPS.PBPS2} 0U)) #endif /* Permanent Block Protection Register 3 */ #ifndef BSP_CFG_ROM_REG_PBPS3 #define BSP_CFG_ROM_REG_PBPS3 (~(${config.bsp.fsp.PBPS.PBPS3} 0U)) #endif /* Security Attribution for Block Protection Register 0 (If any blocks are marked as protected in the secure application, then mark them as secure) */ #ifndef BSP_CFG_ROM_REG_BPS_SEL0 #define BSP_CFG_ROM_REG_BPS_SEL0 (BSP_CFG_ROM_REG_BPS0 & BSP_CFG_ROM_REG_PBPS0) #endif /* Security Attribution for Block Protection Register 1 (If any blocks are marked as protected in the secure application, then mark them as secure) */ #ifndef BSP_CFG_ROM_REG_BPS_SEL1 #define BSP_CFG_ROM_REG_BPS_SEL1 (BSP_CFG_ROM_REG_BPS1 & BSP_CFG_ROM_REG_PBPS1) #endif /* Security Attribution for Block Protection Register 2 (If any blocks are marked as protected in the secure application, then mark them as secure) */ #ifndef BSP_CFG_ROM_REG_BPS_SEL2 #define BSP_CFG_ROM_REG_BPS_SEL2 (BSP_CFG_ROM_REG_BPS2 & BSP_CFG_ROM_REG_PBPS2) #endif /* Security Attribution for Block Protection Register 3 (If any blocks are marked as protected in the secure application, then mark them as secure) */ #ifndef BSP_CFG_ROM_REG_BPS_SEL3 #define BSP_CFG_ROM_REG_BPS_SEL3 (BSP_CFG_ROM_REG_BPS3 & BSP_CFG_ROM_REG_PBPS3) #endif /* Security Attribution for Bank Select Register */ #ifndef BSP_CFG_ROM_REG_BANKSEL_SEL #define BSP_CFG_ROM_REG_BANKSEL_SEL (${config.bsp.fsp.tz.banksel_sel}) #endif #ifndef BSP_CLOCK_CFG_MAIN_OSC_WAIT #define BSP_CLOCK_CFG_MAIN_OSC_WAIT (${config.bsp.common.main_osc_wait}) #endif
